import type { MaybeRefOrGetter } from 'vue'
import { computed, toValue, watch } from 'vue'
import { useOverlay } from './useOverlay'

export type FlexibleCreateTile = (...args: Parameters<AMap.TileLayer.FlexibleCreateTile>) => void | Promise<void>

export interface UseFlexibleLayerOptions extends Omit<AMap.TileLayer.FlexibleOptions, 'createTile'> {
  /** Finish each tile by calling success with an image or canvas, or by calling fail. */
  createTile: FlexibleCreateTile
}

/** Attach a layer whose tiles are generated by the application. */
export function useFlexibleLayer(
  map: MaybeRefOrGetter<AMap.Map | null | undefined>,
  options: MaybeRefOrGetter<UseFlexibleLayerOptions>,
) {
  let attached: AMap.TileLayer.Flexible | null = null
  let generation = 0

  const api = useOverlay(
    map,
    options,
    ({ AMap, options: { createTile: _createTile, ...settings } }) => {
      const layer = new AMap.TileLayer.Flexible({
        ...settings,
        createTile(x, y, z, success, fail) {
          if (!attached || attached !== layer) {
            fail()
            return
          }

          const current = generation
          let settled = false
          function settle(callback: () => void) {
            if (settled || generation !== current || attached !== layer)
              return
            settled = true
            callback()
          }

          const onFailure = () => settle(fail)
          try {
            const pending = toValue(options).createTile(x, y, z, tile => settle(() => success(tile)), onFailure)
            if (pending)
              void pending.catch(onFailure)
          }
          catch {
            onFailure()
          }
        },
      })
      return layer
    },
    undefined,
    undefined,
    {
      recreateOnMapChange: true,
      attach(map, layer) {
        attached = layer
        layer.setMap(map)
      },
      detach(_map, layer) {
        attached = null
        generation++
        layer.setMap(null)
      },
    },
  )

  const { overlay } = api
  const zooms = computed(() => toValue(options).zooms)
  function reload() {
    generation++
    overlay.value?.reload()
  }

  watch(() => toValue(options).createTile, reload)
  watch(zooms, (value) => {
    if (value)
      overlay.value?.setZooms(value)
  }, { deep: true })
  watch(() => toValue(options).opacity, opacity => overlay.value?.setOpacity(opacity ?? 1))
  watch(() => toValue(options).zIndex, zIndex => overlay.value?.setzIndex(zIndex ?? 4))
  watch(() => toValue(options).visible, (visible) => {
    if (visible === false)
      overlay.value?.hide()
    else
      overlay.value?.show()
  })

  return { ...api, reload }
}
